import{_ as n,a as o,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 单元 2 语法总结 · 现在完成时与过去时间至情态动词的意义与形式","description":"L25–L48 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 2 语法总结 · 现在完成时与过去时间至情态动词的意义与形式","description":"L25–L48 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-02/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 2 语法总结","summary":"L25–L48 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 2 语法总结 · 间接引语与视角转换至动名词与动词搭配","link":"/life/english/new-concept/book-2/unit-02/grammar-part-01"},"next":{"text":"第二册：实践与进步 · 单元 2 语法总结 · 动词、宾语与补足语至时间、原因与让步从句","link":"/life/english/new-concept/book-2/unit-02/grammar-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 2 语法总结 · 间接引语与视角转换至动名词与动词搭配","link":"/life/english/new-concept/book-2/unit-02/grammar-part-01"},"next":{"text":"第二册：实践与进步 · 单元 2 语法总结 · 动词、宾语与补足语至时间、原因与让步从句","link":"/life/english/new-concept/book-2/unit-02/grammar-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/grammar-part-02.md","filePath":"life/english/new-concept/book-2/unit-02/grammar-part-02.md"}'),r={name:"life/english/new-concept/book-2/unit-02/grammar-part-02.md"};function i(s,e,l,p,h,c){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-2-语法总结-·-现在完成时与过去时间至情态动词的意义与形式" tabindex="-1">第二册：实践与进步 · 单元 2 语法总结 · 现在完成时与过去时间至情态动词的意义与形式 <a class="header-anchor" href="#第二册-实践与进步-·-单元-2-语法总结-·-现在完成时与过去时间至情态动词的意义与形式" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 2 语法总结 · 现在完成时与过去时间至情态动词的意义与形式&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-02/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元复习与自测</a></p><h2 id="现在完成时与过去时间" tabindex="-1">现在完成时与过去时间 <a class="header-anchor" href="#现在完成时与过去时间" aria-label="Permalink to &quot;现在完成时与过去时间 {#现在完成时与过去时间}&quot;">​</a></h2><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：has carried 统计到当前的乘客数量；a hundred passengers 不表示一次飞行装载一百人，应根据时间范围理解累计。</p><p><strong>L29 原创例句：</strong> The small plane has carried a hundred passengers this week.</p><p>这架小飞机本周已运送一百名乘客。</p><p><strong>易错：</strong> has flew 错误，fly 的过去分词是 flown；本例 carry 的过去分词是 carried。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-029">Lesson 29</a></p><h2 id="冠词与可数性" tabindex="-1">冠词与可数性 <a class="header-anchor" href="#冠词与可数性" aria-label="Permalink to &quot;冠词与可数性 {#冠词与可数性}&quot;">​</a></h2><p>a/an 引入一个尚未特指的可数单数名词，an 的选择取决于后面词的开头读音；the 用于听者能确定的对象或特定范围。泛指复数和不可数名词时常不用冠词。可数性也会随词义变化，如 coffee 可指饮料，也可指一杯饮料。不要把每个汉语名词都配上 a；先判断本句中的词义、数量及听者能否辨认对象。本课应用：第一次提到 a ball 后，再说 the ball 表同一只球；river 若已经由场景明确可用 the，不意味着所有河流名词前都一律用 the。</p><p><strong>L30 原创例句：</strong> A ball landed in the river beside our picnic spot.</p><p>一个球落进了我们野餐地点旁的河里。</p><p><strong>易错：</strong> on the river 通常表示在河面上，into the river 强调从外面进入水中。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-030">Lesson 30</a></p><h2 id="被动语态与信息重点" tabindex="-1">被动语态与信息重点 <a class="header-anchor" href="#被动语态与信息重点" aria-label="Permalink to &quot;被动语态与信息重点 {#被动语态与信息重点}&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：has been found 说明东西已经找回，与现在有关；was found yesterday 用于明确昨天的事件。被动不代表执行者必定未知，只是可以不写。</p><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：will be opened 表未来开放事件；is being built 表当前施工。两种被动可在同一工程说明中分别交代现在与将来。</p><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：has been returned 交代现在钱已归还；was left 说明信封在过去被放置的行为。证据只能支持归还事实，不一定支持动机判断。</p><p><strong>L32 原创例句：</strong> The missing receipt has been found behind the counter.</p><p>丢失的收据已经在柜台后面找到了。</p><p><strong>L37 原创例句：</strong> The new stadium will be opened in September.</p><p>新体育场将在九月开放。</p><p><strong>L45 原创例句：</strong> The missing money has been returned in a plain envelope.</p><p>丢失的钱已经装在一个普通信封里归还了。</p><p><strong>易错：</strong> has found the receipt 是主动；receipt has found 缺少合理宾语且让收据成为发现者。</p><p>The event will be taken place 错误；take place 本身是不及物表达。</p><p>money have been 应为 money has been；不可数名词按单数处理。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-032">Lesson 32</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-037">Lesson 37</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-045">Lesson 45</a></p><h2 id="不定式与目的" tabindex="-1">不定式与目的 <a class="header-anchor" href="#不定式与目的" aria-label="Permalink to &quot;不定式与目的 {#不定式与目的}&quot;">​</a></h2><p>to 加动词原形可以作某些动词的宾语、名词后的修饰语或表示目的的状语。表示目的时，执行不定式动作的人通常与主句主语一致；不一致时需明确另一个逻辑主语，如 for somebody to do。否定一般写 not to do。情态动词后、make/let 主动结构中通常用不带 to 的原形，不能因为看到两个动词就一律在中间加入 to。本课应用：stopped to help 表停下原来活动去帮忙；stopped helping 则表示停止帮助。两种结构的动作先后和目的不同。</p><p><strong>L35 原创例句：</strong> A cyclist stopped to help the shop assistant.</p><p>一位骑车人停下来帮助店员。</p><p><strong>易错：</strong> stop to run 是停下别的事去跑；stop running 是不再跑。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-035">Lesson 35</a></p><h2 id="将来进行时与过程" tabindex="-1">将来进行时与过程 <a class="header-anchor" href="#将来进行时与过程" aria-label="Permalink to &quot;将来进行时与过程 {#将来进行时与过程}&quot;">​</a></h2><p>将来进行时使用 will be 加动词 -ing，突出未来某个时间正在发生的过程，常用于说明正常安排中的活动。它与 will do 的区别主要是观察角度：一个看过程，一个把动作看成整体。句中须有明确或可推知的未来参照时间。不要把 will be 后面接原形误当进行时，也不要用它保证某项活动一定完成；完成结果需要其他表达。本课应用：will be swimming 指届时的过程，不保证成功到达；will have finished 才突出某时之前完成，但需要合理的计划或预测依据。</p><p><strong>L36 原创例句：</strong> At noon tomorrow, Ava will be swimming near the eastern coast.</p><p>明天中午，艾娃将在东海岸附近游泳。</p><p><strong>易错：</strong> will be swum 是被动形式，不表示她自己正在游；此处用 swimming。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-036">Lesson 36</a></p><h2 id="非真实条件句" tabindex="-1">非真实条件句 <a class="header-anchor" href="#非真实条件句" aria-label="Permalink to &quot;非真实条件句 {#非真实条件句}&quot;">​</a></h2><p>与现在事实不同或可能性较小的假设常用 if 加过去式，主句用 would/could 加原形；与过去事实相反则用 if 加 had done，主句用 would/could have done。这里的过去形式主要表达距离感，不总指过去时间。be 在正式假设中可用 were。选择句型前先确定假设发生的时间，再检查结果的时间，不要把真实未来条件与虚拟假设混用。本课应用：If I knew ... I would ... 是对当前知识不足的假设，不是昨天发生的事。would 后接原形，不放进通常的 if 条件部分。</p><p><strong>L40 原创例句：</strong> If I knew more about her work, I would ask better questions.</p><p>如果我更了解她的工作，我就会问出更好的问题。</p><p><strong>易错：</strong> If I would know 通常不能表达这种标准假设；用 If I knew。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-040">Lesson 40</a></p><h2 id="情态动词的意义与形式" tabindex="-1">情态动词的意义与形式 <a class="header-anchor" href="#情态动词的意义与形式" aria-label="Permalink to &quot;情态动词的意义与形式 {#情态动词的意义与形式}&quot;">​</a></h2><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：need not buy 表没有购买必要，不表示禁止购买；must not buy 才是否定许可。对方可以拒绝建议，句子的语气不能混为一谈。</p><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：was able to land 在单次事件里明确成功降落；could land 可能只说明具备能力或可能性。一般性过去能力通常可用 could。</p><p><strong>L41 原创例句：</strong> You need not buy the hat just because it is fashionable.</p><p>你不必仅仅因为这顶帽子时髦就买它。</p><p><strong>L43 原创例句：</strong> The pilot was able to land before the storm arrived.</p><p>飞行员赶在暴风雨到来前成功着陆。</p><p><strong>易错：</strong> need not buy 是不必买，不能译成“不准买”；do not need to buy 也是不必买。</p><p>managed landing 不符合常用搭配；用 managed to land。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-041">Lesson 41</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-043">Lesson 43</a></p>',57)])])}const u=n(r,[["render",i]]);export{g as __pageData,u as default};
